     1→require("dotenv").config();
     2→const { SolanaTracker } = require("solana-swap");
     3→const { Keypair, PublicKey, Connection } = require("@solana/web3.js");
     4→const bs58 = require("bs58");
     5→const winston = require("winston");
     6→const chalk = require("chalk");
     7→const axios = require("axios");
     8→const fs = require("fs").promises;
     9→
    10→const session = axios.create({
    11→  baseURL: "https://data.solanatracker.io/",
    12→  timeout: 10000,
    13→  headers: { "x-api-key": process.env.API_KEY },
    14→});
    15→
    16→const sleep = (ms) => {
    17→  return new Promise((resolve) => setTimeout(resolve, ms));
    18→};
    19→
    20→const logger = winston.createLogger({
    21→  level: "info",
    22→  format: winston.format.combine(
    23→    winston.format.timestamp({
    24→      format: "YYYY-MM-DD HH:mm:ss",
    25→    }),
    26→    winston.format.printf(
    27→      (info) => `${info.timestamp} ${info.level}: ${info.message}`
    28→    )
    29→  ),
    30→  transports: [
    31→    new winston.transports.Console(),
    32→    new winston.transports.File({ filename: "trading-bot.log" }),
    33→  ],
    34→});
    35→
    36→class TradingBot {
    37→  constructor() {
    38→    this.config = {
    39→      amount: parseFloat(process.env.AMOUNT),
    40→      delay: parseInt(process.env.DELAY),
    41→      monitorInterval: parseInt(process.env.MONITOR_INTERVAL),
    42→      slippage: parseInt(process.env.SLIPPAGE),
    43→      priorityFee: parseFloat(process.env.PRIORITY_FEE),
    44→      useJito: process.env.JITO === "true",
    45→      rpcUrl: process.env.RPC_URL,
    46→      minLiquidity: parseFloat(process.env.MIN_LIQUIDITY) || 0,
    47→      maxLiquidity: parseFloat(process.env.MAX_LIQUIDITY) || Infinity,
    48→      minMarketCap: parseFloat(process.env.MIN_MARKET_CAP) || 0,
    49→      maxMarketCap: parseFloat(process.env.MAX_MARKET_CAP) || Infinity,
    50→      minRiskScore: parseInt(process.env.MIN_RISK_SCORE) || 0,
    51→      maxRiskScore: parseInt(process.env.MAX_RISK_SCORE) || 10,
    52→      requireSocialData: process.env.REQUIRE_SOCIAL_DATA === "true",
    53→      maxNegativePnL: parseFloat(process.env.MAX_NEGATIVE_PNL) || -Infinity,
    54→      maxPositivePnL: parseFloat(process.env.MAX_POSITIVE_PNL) || Infinity,
    55→      markets: process.env.MARKETS?.split(",").map((m) => m.trim()) || ['raydium', 'orca', 'pumpfun', 'moonshot', 'raydium-cpmm'],
    56→    };
    57→
    58→    this.privateKey = process.env.PRIVATE_KEY;
    59→    this.SOL_ADDRESS = "So11111111111111111111111111111111111111112";
    60→    this.positions = new Map();
    61→    this.positionsFile = "positions.json";
    62→    this.soldPositionsFile = "sold_positions.json";
    63→    this.soldPositions = [];
    64→    this.seenTokens = new Set();
    65→    this.buyingTokens = new Set();
    66→    this.sellingPositions = new Set();
    67→
    68→    this.connection = new Connection(this.config.rpcUrl);
    69→  }
    70→
    71→  async initialize() {
    72→    this.keypair = Keypair.fromSecretKey(bs58.decode ? bs58.decode (this.privateKey): bs58.default.decode(this.privateKey));
    73→    this.solanaTracker = new SolanaTracker(this.keypair, this.config.rpcUrl);
    74→    await this.loadPositions();
    75→    await this.loadSoldPositions();
    76→  }
    77→
    78→  async fetchTokens() {
    79→    try {
    80→      const response = await session.get("/tokens/latest");
    81→      return response.data;
    82→    } catch (error) {
    83→      logger.error(`Error fetching token data [${error?.response?.data || error}]`);
    84→      return [];
    85→    }
    86→  }
    87→
    88→  async fetchTokenData(tokenId) {
    89→    try {
    90→      const response = await session.get(`/tokens/${tokenId}`);
    91→      return response.data;
    92→    } catch (error) {
    93→      logger.error(`Error fetching token data [${error?.response?.data || error}]`);
    94→      return null
    95→    }
    96→  }
    97→
    98→  filterTokens(tokens) {
    99→    return tokens.filter((token) => {
   100→      const pool = token.pools[0];
   101→      const liquidity = pool.liquidity.usd;
   102→      const marketCap = pool.marketCap.usd;
   103→      const riskScore = token.risk.score;
   104→      const hasSocialData = !!(
   105→        token.token.twitter ||
   106→        token.token.telegram ||
   107→        token.token.website
   108→      );
   109→      const isInAllowedMarket = this.config.markets.includes(pool.market);
   110→
   111→      return (
   112→        liquidity >= this.config.minLiquidity &&
   113→        liquidity <= this.config.maxLiquidity &&
   114→        marketCap >= this.config.minMarketCap &&
   115→        marketCap <= this.config.maxMarketCap &&
   116→        riskScore >= this.config.minRiskScore &&
   117→        riskScore <= this.config.maxRiskScore &&
   118→        (!this.config.requireSocialData || hasSocialData) &&
   119→        isInAllowedMarket &&
   120→        !this.seenTokens.has(token.token.mint) &&
   121→        !this.buyingTokens.has(token.token.mint)
   122→      );
   123→    });
   124→  }
   125→
   126→  async getWalletAmount(wallet, mint, retries = 3) {
   127→    await sleep(5000);
   128→    for (let attempt = 0; attempt <= retries; attempt++) {
   129→      try {
   130→        const tokenAccountInfo =
   131→          await this.connection.getParsedTokenAccountsByOwner(
   132→            new PublicKey(wallet),
   133→            {
   134→              mint: new PublicKey(mint),
   135→            }
   136→          );
   137→
   138→        if (tokenAccountInfo.value) {
   139→          const balance =
   140→            tokenAccountInfo.value[0].account.data.parsed.info.tokenAmount
   141→              .uiAmount;
   142→
   143→          if (balance > 0) {
   144→            return balance;
   145→          }
   146→        }
   147→
   148→        if (attempt < retries) {
   149→          await sleep(10000);
   150→        }
   151→      } catch (error) {
   152→        if (attempt < retries) {
   153→          await sleep(10000);
   154→        } else {
   155→          logger.error(
   156→            `All attempts failed. Error getting wallet amount for token ${mint}:`,
   157→            error
   158→          );
   159→        }
   160→      }
   161→    }
   162→
   163→    logger.warn(
   164→      `Failed to get wallet amount for token ${mint} after ${retries} retries.`
   165→    );
   166→    return null;
   167→  }
   168→
   169→  async performSwap(token, isBuy) {
   170→    logger.info(
   171→      `${
   172→        isBuy ? chalk.white("[BUYING]") : chalk.white("[SELLING]")
   173→      } [${this.keypair.publicKey.toBase58()}] [${token.token.symbol}] [${
   174→        token.token.mint
   175→      }]`
   176→    );
   177→    const { amount, slippage, priorityFee } = this.config;
   178→    const [fromToken, toToken] = isBuy
   179→      ? [this.SOL_ADDRESS, token.token.mint]
   180→      : [token.token.mint, this.SOL_ADDRESS];
   181→
   182→    try {
   183→      let swapAmount;
   184→      if (isBuy) {
   185→        swapAmount = amount;
   186→      } else {
   187→        const position = this.positions.get(token.token.mint);
   188→        if (!position) {
   189→          logger.error(
   190→            `No position found for ${token.token.symbol} when trying to sell`
   191→          );
   192→          return false;
   193→        }
   194→        swapAmount = position.amount;
   195→      }
   196→
   197→      const swapResponse = await this.solanaTracker.getSwapInstructions(
   198→        fromToken,
   199→        toToken,
   200→        swapAmount,
   201→        slippage,
   202→        this.keypair.publicKey.toBase58(),
   203→        priorityFee
   204→      );
   205→
   206→      const swapOptions = this.buildSwapOptions();
   207→      const txid = await this.solanaTracker.performSwap(
   208→        swapResponse,
   209→        swapOptions
   210→      );
   211→      this.logTransaction(txid, isBuy, token);
   212→
   213→      if (isBuy) {
   214→        const tokenAmount = await this.getWalletAmount(
   215→          this.keypair.publicKey.toBase58(),
   216→          token.token.mint
   217→        );
   218→        if (!tokenAmount) {
   219→          logger.error(
   220→            `Swap failed ${token.token.mint}`
   221→          );
   222→          return false;
   223→        }
   224→        this.positions.set(token.token.mint, {
   225→          txid,
   226→          symbol: token.token.symbol,
   227→          entryPrice: token.pools[0].price.quote,
   228→          amount: tokenAmount,
   229→          openTime: Date.now(),
   230→        });
   231→        this.seenTokens.add(token.token.mint);
   232→        this.buyingTokens.delete(token.token.mint);
   233→      } else {
   234→        const position = this.positions.get(token.token.mint);
   235→        if (position) {
   236→          const exitPrice = token.pools[0].price.quote;
   237→          const pnl = (exitPrice - position.entryPrice) * position.amount;
   238→          const pnlPercentage =
   239→            (pnl / (position.entryPrice * position.amount)) * 100;
   240→
   241→          const soldPosition = {
   242→            ...position,
   243→            exitPrice,
   244→            pnl,
   245→            pnlPercentage,
   246→            closeTime: Date.now(),
   247→            closeTxid: txid,
   248→          };
   249→
   250→          this.soldPositions.push(soldPosition);
   251→
   252→          logger.info(
   253→            `Closed position for ${token.token.symbol}. PnL: (${pnlPercentage.toFixed(2)}%)`
   254→          );
   255→          this.positions.delete(token.token.mint);
   256→          this.sellingPositions.delete(token.token.mint);
   257→
   258→          await this.saveSoldPositions();
   259→        }
   260→      }
   261→
   262→      await this.savePositions();
   263→      return txid;
   264→    } catch (error) {
   265→      logger.error(
   266→        `Error performing ${isBuy ? "buy" : "sell"}: ${error.message}`,
   267→        { error }
   268→      );
   269→      if (isBuy) {
   270→        this.buyingTokens.delete(token.token.mint);
   271→      } else {
   272→        this.sellingPositions.delete(token.token.mint);
   273→      }
   274→      return false;
   275→    }
   276→  }
   277→
   278→  async checkAndSellPosition(tokenMint) {
   279→    if (this.sellingPositions.has(tokenMint)) {
   280→    //  logger.info(`Already selling position for ${tokenMint}, skipping`);
   281→      return;
   282→    }
   283→
   284→    const position = this.positions.get(tokenMint);
   285→    if (!position) return;
   286→
   287→    const tokenData = await this.fetchTokenData(tokenMint);
   288→    if (!tokenData) {
   289→      logger.error(`Failed to fetch data for token ${tokenMint}`);
   290→      return;
   291→    }
   292→
   293→    const currentPrice = tokenData.pools[0].price.quote;
   294→    const pnlPercentage =
   295→      ((currentPrice - position.entryPrice) / position.entryPrice) * 100;
   296→
   297→    logger.info(
   298→      `PnL for position [${position.symbol}] [${chalk[
   299→        pnlPercentage > 0 ? "green" : "red"
   300→      ](pnlPercentage.toFixed(2))}%]`
   301→    );
   302→
   303→    if (
   304→      pnlPercentage <= this.config.maxNegativePnL ||
   305→      pnlPercentage >= this.config.maxPositivePnL
   306→    ) {
   307→      const currentAmount = await this.getWalletAmount(
   308→        this.keypair.publicKey.toBase58(),
   309→        tokenMint
   310→      );
   311→      if (currentAmount !== null && currentAmount > 0) {
   312→        this.sellingPositions.add(tokenMint);
   313→        this.performSwap(tokenData, false).catch((error) => {
   314→          logger.error(`Error selling position: ${error.message}`, { error });
   315→          this.sellingPositions.delete(tokenMint);
   316→        });
   317→      } else {
   318→        logger.warn(
   319→          `No balance found for ${position.symbol}, removing from positions`
   320→        );
   321→        this.positions.delete(tokenMint);
