## Part 3: Platform Adapters Implementation

### 3.1 Circuit Breaker and Retry Logic

Following resilience patterns from the PRD:

```typescript
// src/adapters/base/circuit-breaker.ts

import { 
  CircuitBreakerPolicy, 
  ExponentialBackoff, 
  RetryPolicy,
  BulkheadPolicy,
  TimeoutPolicy,
  Policy,
  handleAll
} from 'cockatiel';
import { logger } from '@utils/logger';

export function createPlatformResilience(platformName: string) {
  // Circuit breaker: Open after 5 failures, half-open after 30s
  const circuitBreaker = Policy.handleAll()
    .circuitBreaker(30_000, {
      halfOpenAfter: 30_000,
      breaker: {
        threshold: 5,
        duration: 60_000
      }
    });

  // Retry with exponential backoff + jitter (max 3 retries)
  const retry = Policy.handleAll()
    .retry()
    .exponential({
      maxAttempts: 3,
      initialDelay: 1000,
      maxDelay: 10_000,
      exponent: 2
    });

  // Bulkhead: Max 5 concurrent requests per platform
  const bulkhead = Policy.bulkhead(5, 10);

  // Timeout: 10 seconds per request
  const timeout = Policy.timeout(10_000, 'aggressive');

  // Compose policies: timeout -> retry -> circuit breaker -> bulkhead
  const policy = Policy.wrap(timeout, retry, circuitBreaker, bulkhead);

  // Add event listeners for monitoring
  circuitBreaker.onStateChange((state) => {
    logger.warn(`[${platformName}] Circuit breaker state: ${state}`);
  });

  return { policy, circuitBreaker, bulkhead };
}
```

### 3.2 StubHub Adapter

```typescript
// src/adapters/stubhub/stubhub.adapter.ts

import axios, { AxiosInstance } from 'axios';
import { 
  IPlatformAdapter, 
  PlatformConfig, 
  EventSearchParams,
  NormalizedEvent,
  NormalizedListing 
} from '../base/platform-adapter.interface';
import { createPlatformResilience } from '../base/circuit-breaker';
import { StubHubEventResponse, StubHubListingResponse } from './stubhub.types';
import { mapToNormalizedEvent, mapToNormalizedListing } from './stubhub.mapper';
import { logger } from '@utils/logger';
import { config } from '@config/index';

export class StubHubAdapter implements IPlatformAdapter {
  readonly config: PlatformConfig = {
    name: 'stubhub',
    baseUrl: 'https://api.stubhub.com',
    rateLimit: { requestsPerMinute: 10 },
    timeout: 10_000,
    retryAttempts: 3
  };

  private client: AxiosInstance;
  private accessToken: string | null = null;
  private tokenExpiry: Date | null = null;
  readonly circuitBreaker;
  private readonly resilience;

  constructor() {
    this.resilience = createPlatformResilience('stubhub');
    this.circuitBreaker = this.resilience.circuitBreaker;

    this.client = axios.create({
      baseURL: this.config.baseUrl,
      timeout: this.config.timeout,
      headers: {
        'Accept': 'application/json',
        'Content-Type': 'application/json'
      }
    });
  }

  async initialize(): Promise<void> {
    await this.refreshAccessToken();
    logger.info('[StubHub] Adapter initialized');
  }

  private async refreshAccessToken(): Promise<void> {
    const response = await axios.post(
      'https://api.stubhub.com/sellers/oauth/accesstoken',
      new URLSearchParams({
        grant_type: 'client_credentials',
        scope: 'read:events'
      }),
      {
        auth: {
          username: config.stubhub.clientId,
          password: config.stubhub.clientSecret
        },
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
      }
    );

    this.accessToken = response.data.access_token;
    this.tokenExpiry = new Date(Date.now() + (response.data.expires_in * 1000));

    this.client.defaults.headers.common['Authorization'] = 
      `Bearer ${this.accessToken}`;
  }

  private async ensureValidToken(): Promise<void> {
    if (!this.accessToken || !this.tokenExpiry || 
        this.tokenExpiry.getTime() - Date.now() < 60_000) {
      await this.refreshAccessToken();
    }
  }

  async searchEvents(params: EventSearchParams): Promise<NormalizedEvent[]> {
    await this.ensureValidToken();

    return this.resilience.policy.execute(async () => {
      const response = await this.client.get<StubHubEventResponse>(
        '/catalog/events',
        {
          params: {
            city: params.city,
            minDate: params.startDate.toISOString(),
            maxDate: params.endDate.toISOString(),
            rows: 100
          }
        }
      );

      return response.data.events.map(mapToNormalizedEvent);
    });
  }

  async getEventListings(platformEventId: string): Promise<NormalizedListing[]> {
    await this.ensureValidToken();

    return this.resilience.policy.execute(async () => {
      const response = await this.client.get<StubHubListingResponse>(
        `/catalog/events/${platformEventId}/listings`,
        {
          params: {
            rows: 250,
            sort: 'price asc'
          }
        }
      );

      return response.data.listings.map(listing => 
        mapToNormalizedListing(listing, platformEventId)
      );
    });
  }

  async getHealthStatus(): Promise<{ healthy: boolean; latency: number }> {
    const start = Date.now();
    try {
      await this.client.get('/status');
      return { healthy: true, latency: Date.now() - start };
    } catch {
      return { healthy: false, latency: Date.now() - start };
    }
  }
}
