import { 
  IPlatformAdapter, 
  PlatformConfig,
  EventSearchParams,
  NormalizedEvent,
  NormalizedListing 
} from '../base/platform-adapter.interface';
import { createPlatformResilience } from '../base/circuit-breaker';
import { 
  TicketmasterEventResponse, 
  TicketmasterOffersResponse 
} from './ticketmaster.types';
import { mapToNormalizedEvent, mapToNormalizedListing } from './ticketmaster.mapper';
import { logger } from '@utils/logger';
import { config } from '@config/index';
import { RateLimiter } from '@utils/rate-limiter';

export class TicketmasterAdapter implements IPlatformAdapter {
  readonly config: PlatformConfig = {
    name: 'ticketmaster',
    baseUrl: 'https://app.ticketmaster.com/discovery/v2',
    rateLimit: { requestsPerDay: 5000 },
    timeout: 10_000,
    retryAttempts: 3
  };

  private client: AxiosInstance;
  private rateLimiter: RateLimiter;
  readonly circuitBreaker;
  private readonly resilience;

  constructor() {
    this.resilience = createPlatformResilience('ticketmaster');
    this.circuitBreaker = this.resilience.circuitBreaker;

    // 5000 requests/day = ~3.5 requests/minute average
    this.rateLimiter = new RateLimiter({
      tokensPerInterval: 5,
      interval: 'minute'
    });

    this.client = axios.create({
      baseURL: this.config.baseUrl,
      timeout: this.config.timeout,
      params: {
        apikey: config.ticketmaster.apiKey
      }
    });
  }

  async initialize(): Promise<void> {
    logger.info('[Ticketmaster] Adapter initialized');
  }

  async searchEvents(params: EventSearchParams): Promise<NormalizedEvent[]> {
    await this.rateLimiter.acquire();

    return this.resilience.policy.execute(async () => {
      const response = await this.client.get<TicketmasterEventResponse>(
        '/events',
        {
          params: {
            city: params.city,
            stateCode: this.getStateCode(params.city),
            startDateTime: params.startDate.toISOString().split('.')[0] + 'Z',
            endDateTime: params.endDate.toISOString().split('.')[0] + 'Z',
            size: 100,
            sort: 'date,asc'
          }
        }
      );

      const events = response.data._embedded?.events || [];
      return events.map(mapToNormalizedEvent);
    });
  }

  async getEventListings(platformEventId: string): Promise<NormalizedListing[]> {
    await this.rateLimiter.acquire();

    return this.resilience.policy.execute(async () => {
      const response = await this.client.get<TicketmasterOffersResponse>(
        `/events/${platformEventId}/offers`
      );

      return response.data.offers
        .filter(offer => offer.type === 'resale')
        .map(offer => mapToNormalizedListing(offer, platformEventId));
    });
  }

  private getStateCode(city: string): string {
    const cityToState: Record<string, string> = {
      'portland': 'OR',
      'seattle': 'WA',
      'tacoma': 'WA',
      'eugene': 'OR',
      'spokane': 'WA',
      'boise': 'ID'
    };
    return cityToState[city.toLowerCase()] || 'WA';
  }

  async getHealthStatus(): Promise<{ healthy: boolean; latency: number }> {
    const start = Date.now();
    try {
      await this.client.get('/events', { params: { size: 1 } });
      return { healthy: true, latency: Date.now() - start };
    } catch {
      return { healthy: false, latency: Date.now() - start };
    }
  }
}
