## Part 4: Value Score Engine

### 4.1 Value Engine Service

```typescript
// src/services/value-engine/value-engine.service.ts

import {
  ValueScoreWeights,
  ValueScoreInput,
  ValueScoreResult,
  SectionTier
} from './value-score.types';
import { PriceAnalyzer } from './scoring/price-analyzer';
import { SectionRanker } from './scoring/section-ranker';
import { RowEvaluator } from './scoring/row-evaluator';
import { ResalePredictor } from './scoring/resale-predictor';
import { logger } from '@utils/logger';

export class ValueEngineService {
  private readonly weights: ValueScoreWeights = {
    priceVsAverage: 0.35,
    sectionQuality: 0.25,
    rowPosition: 0.15,
    historicalPricing: 0.15,
    resalePotential: 0.10
  };

  private priceAnalyzer: PriceAnalyzer;
  private sectionRanker: SectionRanker;
  private rowEvaluator: RowEvaluator;
  private resalePredictor: ResalePredictor;

  constructor() {
    this.priceAnalyzer = new PriceAnalyzer();
    this.sectionRanker = new SectionRanker();
    this.rowEvaluator = new RowEvaluator();
    this.resalePredictor = new ResalePredictor();
  }

  calculateValueScore(input: ValueScoreInput): ValueScoreResult {
    // 1. Price vs Average (35%) - Lower price = higher score
    const priceScore = this.priceAnalyzer.analyze(
      input.listing.pricePerTicket,
      input.averagePrice
    );

    // 2. Section Quality (25%) - Premium sections score higher
    const sectionScore = this.sectionRanker.rank(input.sectionTier);

    // 3. Row Position (15%) - Front rows score higher
    const rowScore = this.rowEvaluator.evaluate(
      input.rowRank,
      input.totalRowsInSection
    );

    // 4. Historical Pricing (15%) - Below historical average = higher score
    const historicalScore = this.priceAnalyzer.analyzeHistorical(
      input.listing.pricePerTicket,
      input.historicalPriceData
    );

    // 5. Resale Potential (10%) - High demand + good timing = higher score
    const resaleScore = this.resalePredictor.predict(
      input.eventPopularity,
      input.daysUntilEvent,
      input.sectionTier
    );

    // Calculate weighted total
    const totalScore = Math.round(
      (priceScore * this.weights.priceVsAverage) +
      (sectionScore * this.weights.sectionQuality) +
      (rowScore * this.weights.rowPosition) +
      (historicalScore * this.weights.historicalPricing) +
      (resaleScore * this.weights.resalePotential)
    );

    const recommendation = this.getRecommendation(totalScore);
    const reasoning = this.generateReasoning(
      { priceScore, sectionScore, rowScore, historicalScore, resaleScore },
      totalScore
    );

    return {
      totalScore: Math.min(100, Math.max(1, totalScore)),
      breakdown: {
        priceScore,
        sectionScore,
        rowScore,
        historicalScore,
        resaleScore
      },
      recommendation,
      reasoning
    };
  }

  private getRecommendation(score: number): ValueScoreResult['recommendation'] {
    if (score >= 85) return 'excellent';
    if (score >= 70) return 'good';
    if (score >= 55) return 'fair';
    if (score >= 40) return 'below_average';
    return 'poor';
  }

  private generateReasoning(
    breakdown: ValueScoreResult['breakdown'],
    total: number
  ): string {
    const reasons: string[] = [];

    if (breakdown.priceScore >= 80) {
      reasons.push('Exceptional price below market average');
    } else if (breakdown.priceScore <= 40) {
      reasons.push('Price is above market average');
    }

    if (breakdown.sectionScore >= 80) {
      reasons.push('Premium seating location');
    }

    if (breakdown.historicalScore >= 80) {
      reasons.push('Price is near historical low');
    }

    return reasons.length > 0 
      ? reasons.join('. ') + '.'
      : `Value score of ${total} based on multiple factors.`;
  }

  getTopValuePicks(
    listings: Array<{ listing: NormalizedListing; score: ValueScoreResult }>,
    limit: number = 10
  ): Array<{ listing: NormalizedListing; score: ValueScoreResult }> {
    return listings
      .sort((a, b) => b.score.totalScore - a.score.totalScore)
      .slice(0, limit);
  }
}
