### 4.2 Price Analyzer Component

```typescript
// src/services/value-engine/scoring/price-analyzer.ts

import { HistoricalPrice } from '../value-score.types';

export class PriceAnalyzer {
  /**
   * Analyze price vs current market average
   * Returns score 0-100 where lower price = higher score
   */
  analyze(price: number, averagePrice: number): number {
    if (averagePrice <= 0) return 50;

    const priceDifferencePercent = ((averagePrice - price) / averagePrice) * 100;

    // Map to 0-100 score:
    // 50% below average = 100
    // At average = 50
    // 50% above average = 0
    const score = 50 + priceDifferencePercent;

    return Math.min(100, Math.max(0, score));
  }

  /**
   * Analyze price vs historical data
   * Returns score 0-100 based on how price compares to historical trends
   */
  analyzeHistorical(
    currentPrice: number,
    historicalData: HistoricalPrice[]
  ): number {
    if (historicalData.length === 0) return 50;

    // Calculate historical average and lowest
    const avgHistoricalPrice = historicalData.reduce(
      (sum, h) => sum + h.averagePrice, 0
    ) / historicalData.length;

    const lowestHistoricalPrice = Math.min(
      ...historicalData.map(h => h.lowestPrice)
    );

    // Score based on position between lowest and average
    if (currentPrice <= lowestHistoricalPrice) {
      return 100; // At or below historical low
    }

    if (currentPrice >= avgHistoricalPrice) {
      // Above average - map to 0-50 range
      const overage = (currentPrice - avgHistoricalPrice) / avgHistoricalPrice;
      return Math.max(0, 50 - (overage * 100));
    }

    // Between lowest and average - map to 50-100 range
    const range = avgHistoricalPrice - lowestHistoricalPrice;
    const position = (avgHistoricalPrice - currentPrice) / range;
    return 50 + (position * 50);
  }
}
