```typescript
// src/notifications/telegram/telegram.notifier.ts

import { Telegraf } from 'telegraf';
import { 
  INotifier, 
  AlertPayload, 
  NotificationResult 
} from '../base/notifier.interface';
import { TelegramFormatter } from './telegram.formatter';
import { logger } from '@utils/logger';
import { config } from '@config/index';

export class TelegramNotifier implements INotifier {
  readonly channel = 'telegram' as const;
  private bot: Telegraf;
  private formatter: TelegramFormatter;

  constructor() {
    this.bot = new Telegraf(config.telegram.botToken);
    this.formatter = new TelegramFormatter();
  }

  async initialize(): Promise<void> {
    // Verify bot token
    const botInfo = await this.bot.telegram.getMe();
    logger.info(`[Telegram] Bot initialized: @${botInfo.username}`);
  }

  async sendAlert(payload: AlertPayload): Promise<NotificationResult> {
    try {
      const message = this.formatter.formatAlert(payload);

      const result = await this.bot.telegram.sendMessage(
        payload.userId, // Telegram chat ID
        message,
        {
          parse_mode: 'MarkdownV2',
          disable_web_page_preview: false
        }
      );

      logger.info(`[Telegram] Alert sent to ${payload.userId}`);

      return {
        success: true,
        channel: 'telegram',
        messageId: result.message_id.toString(),
        timestamp: new Date()
      };
    } catch (error) {
      logger.error(`[Telegram] Failed to send alert: ${error}`);
      return {
        success: false,
        channel: 'telegram',
        error: error instanceof Error ? error.message : 'Unknown error',
        timestamp: new Date()
      };
    }
  }

  async validateRecipient(chatId: string): Promise<boolean> {
    try {
      await this.bot.telegram.getChat(chatId);
      return true;
    } catch {
      return false;
    }
  }

  async getDeliveryStatus(messageId: string): Promise<'delivered' | 'pending' | 'failed'> {
    // Telegram doesn't provide delivery status for bots
    // If sendMessage succeeded, consider it delivered
    return 'delivered';
  }
