### 5.2 Telegram Formatter

```typescript
// src/notifications/telegram/telegram.formatter.ts

import { AlertPayload, TopValueListing } from '../base/notifier.interface';

export class TelegramFormatter {
  formatAlert(payload: AlertPayload): string {
    const header = this.escapeMarkdown(
      `🎫 ${payload.eventName}\n` +
      `📍 ${payload.venueName}\n` +
      `📅 ${this.formatDate(payload.eventDate)}\n\n` +
      `🔥 TOP ${payload.listings.length} VALUE PICKS:`
    );

    const listings = payload.listings
      .map(l => this.formatListing(l))
      .join('\n\n');

    const footer = this.escapeMarkdown(
      '\n\n⚠️ Prices subject to change. Click links to purchase.'
    );

    return header + '\n\n' + listings + footer;
  }

  private formatListing(listing: TopValueListing): string {
    const scoreEmoji = this.getScoreEmoji(listing.valueScore);
    const platformBadge = listing.platform === 'stubhub' ? '🟢' : '🔵';

    return this.escapeMarkdown(
      `${listing.rank}. ${platformBadge} Section ${listing.section}, Row ${listing.row}\n` +
      `   💰 $${listing.pricePerTicket}/ticket (${listing.quantity} avail)\n` +
      `   ${scoreEmoji} Value Score: ${listing.valueScore}/100\n`
    ) + `   [Buy Now](${listing.deepLink})`;
  }

  private getScoreEmoji(score: number): string {
    if (score >= 85) return '🌟';
    if (score >= 70) return '✨';
    if (score >= 55) return '👍';
    return '📊';
  }

  private formatDate(date: Date): string {
    return date.toLocaleDateString('en-US', {
      weekday: 'short',
      month: 'short',
      day: 'numeric',
      hour: 'numeric',
      minute: '2-digit'
    });
  }

  private escapeMarkdown(text: string): string {
    // Escape MarkdownV2 special characters
    return text.replace(/[_*[\]()~`>#+=|{}.!-]/g, '\\$&');
  }
}
```

### 5.3 Twilio SMS Notifier

```typescript
// src/notifications/twilio/sms.notifier.ts

import twilio from 'twilio';
import { 
  INotifier, 
  AlertPayload, 
  NotificationResult 
} from '../base/notifier.interface';
import { SMSFormatter } from './sms.formatter';
import { logger } from '@utils/logger';
import { config } from '@config/index';

export class SMSNotifier implements INotifier {
  readonly channel = 'sms' as const;
  private client: twilio.Twilio;
  private formatter: SMSFormatter;
  private fromNumber: string;

  constructor() {
    this.client = twilio(
      config.twilio.accountSid,
      config.twilio.authToken
    );
    this.fromNumber = config.twilio.phoneNumber;
    this.formatter = new SMSFormatter();
  }

  async initialize(): Promise<void> {
    // Verify account
    const account = await this.client.api.accounts(config.twilio.accountSid).fetch();
    logger.info(`[Twilio] SMS initialized for account: ${account.friendlyName}`);
  }

  async sendAlert(payload: AlertPayload): Promise<NotificationResult> {
    try {
      const message = this.formatter.formatAlert(payload);

      const result = await this.client.messages.create({
        body: message,
        from: this.fromNumber,
        to: payload.userId // Phone number with country code
      });

      logger.info(`[SMS] Alert sent to ${payload.userId}, SID: ${result.sid}`);

      return {
        success: true,
        channel: 'sms',
        messageId: result.sid,
        timestamp: new Date()
      };
    } catch (error) {
      logger.error(`[SMS] Failed to send alert: ${error}`);
      return {
        success: false,
        channel: 'sms',
        error: error instanceof Error ? error.message : 'Unknown error',
        timestamp: new Date()
      };
    }
  }

  async validateRecipient(phoneNumber: string): Promise<boolean> {
    try {
      const lookup = await this.client.lookups.v2
        .phoneNumbers(phoneNumber)
        .fetch();
      return lookup.valid;
    } catch {
      return false;
    }
  }

  async getDeliveryStatus(
    messageId: string
  ): Promise<'delivered' | 'pending' | 'failed'> {
    const message = await this.client.messages(messageId).fetch();

    switch (message.status) {
      case 'delivered':
        return 'delivered';
      case 'failed':
      case 'undelivered':
        return 'failed';
      default:
        return 'pending';
    }
  }
}
```

