### 6.2 TimescaleDB Hypertables for Time-Series

```sql
-- migrations/002_timescale_hypertables.sql

-- Enable TimescaleDB
CREATE EXTENSION IF NOT EXISTS timescaledb;

-- Price history (time-series data)
CREATE TABLE price_history (
    time TIMESTAMPTZ NOT NULL,
    event_id UUID NOT NULL,
    section VARCHAR(100) NOT NULL,
    avg_price DECIMAL(10,2) NOT NULL,
    min_price DECIMAL(10,2) NOT NULL,
    max_price DECIMAL(10,2) NOT NULL,
    listing_count INTEGER NOT NULL,
    platform VARCHAR(20) NOT NULL
);

-- Convert to hypertable
SELECT create_hypertable('price_history', 'time');

-- Create continuous aggregate for hourly stats
CREATE MATERIALIZED VIEW price_history_hourly
WITH (timescaledb.continuous) AS
SELECT
    time_bucket('1 hour', time) AS bucket,
    event_id,
    section,
    AVG(avg_price)::DECIMAL(10,2) AS avg_price,
    MIN(min_price)::DECIMAL(10,2) AS min_price,
    MAX(max_price)::DECIMAL(10,2) AS max_price,
    SUM(listing_count) AS total_listings
FROM price_history
GROUP BY bucket, event_id, section
WITH NO DATA;

-- Retention policy: Keep detailed data for 30 days
SELECT add_retention_policy('price_history', INTERVAL '30 days');

-- Create indexes on hypertable
CREATE INDEX idx_price_history_event ON price_history(event_id, time DESC);
CREATE INDEX idx_price_history_section ON price_history(event_id, section, time DESC);
```

